  "Auto-hide slides the taskbar away and reveals it when the pointer touches the screen edge. Hidden removes it entirely (desktops still switch with Ctrl+Alt+Left/Right)": "自動非表示はタスクバーをスライドして隠し、ポインタが画面端に触れると表示します。非表示は完全に取り除きます（Ctrl+Alt+左/右 でのデスクトップ切替は可能）",
  "Show the virtual-desktop miniature previews in the taskbar": "タスクバーに仮想デスクトップのミニプレビューを表示",
  "Show the 5h/7d rate-limit donuts in the taskbar": "タスクバーに 5 時間 / 7 日間のレート制限ドーナツを表示",
  "Show the \"N windows\" counter/list button in the taskbar": "タスクバーに「N ウィンドウ」カウンタ/一覧ボタンを表示",
  "Enable Ctrl+\\ command mode for keyboard-driven window management": "Ctrl+\\ コマンドモードを有効化（キーボードでウィンドウ管理）",
  "Snap windows to grid cells or screen edges when dragging": "ドラッグ時にウィンドウをグリッドセルや画面端にスナップ",
  "Hold Shift while dragging title bar to select a range of grid cells": "タイトルバーを Shift を押しながらドラッグしてグリッドセル範囲を選択",
  "How much of the taskbar height the desktop preview occupies (rest goes to label text)": "タスクバーの高さのうちデスクトッププレビューが占める割合（残りはラベル文字）",
  "Which bar hosts each movable element, in what order ({zone: [elementId, …]}). Managed by Customize mode (⚙ → Customize UI… → drag elements); edit by hand only if you know what you are doing.": "各可動要素がどのバーにどの順序で属するか（{zone: [elementId, …]}）。カスタマイズモードで管理（⚙ → Customize UI… → 要素をドラッグ）；理解している場合のみ手動編集してください。",
  "Alignment per area: taskbar-items left/center (Windows-11-style centered icons), toolbar-center left/center/right, taskbar-tray left/right end. Managed by Customize mode.": "エリアごとの整列：タスクバーアイコン 左/中央（Windows 11 風の中央寄せ）、ツールバー中央 左/中/右、タスクバートレイ 左/右端。カスタマイズモードで管理。",
  "Per-spring config: {mode:\"flex\", weight:1-9} (strength = flex-grow share) or {mode:\"fixed\", px:N} (rigid spacer). Managed by Customize mode (click a spring).": "スプリングごとの設定：{mode:\"flex\", weight:1-9}（強さ = flex-grow の配分）または {mode:\"fixed\", px:N}（固定スペーサ）。カスタマイズモードで管理（スプリングをクリック）。",
  "Allow tab bar to wrap into multiple rows when there are many tabs (like a flow layout)": "タブが多いときにタブバーを複数行に折り返す（フローレイアウト）",
  "How prominently the focused window is highlighted (subtle = shadow only, normal = accent border, strong = border + glow)": "フォーカス中ウィンドウの強調度（控えめ = 影のみ、標準 = アクセント枠、強め = 枠 + グロー）",
  "Auto-adjust text colors to meet this contrast ratio (4.5 = WCAG AA). Set to 1 to disable.": "このコントラスト比を満たすよう文字色を自動調整（4.5 = WCAG AA）。1 で無効化。",
  "Keep viewport scroll position anchored when terminal is resized": "ターミナルのリサイズ時にスクロール位置を固定",
  "When to show the orange blink on idle terminals": "アイドル状態のターミナルでオレンジ点滅を表示する条件",
  "Dense document-style layout instead of chat bubbles. Closer to TUI information density.": "吹き出しではなくドキュメント風の高密度レイアウト。TUI に近い情報密度。",
  "How to visually distinguish user vs assistant messages in compact mode.": "コンパクトモードでユーザーとアシスタントのメッセージを見分ける方法。",
  "Default mode for new sessions and single-click resume from sidebar": "新規セッションおよびサイドバーからのシングルクリック再開の既定モード",
  "Select an alias or choose \"Custom...\" to type a specific model ID (e.g. claude-opus-4-6-20250414). Applies to NEW sessions: a resumed conversation keeps the model the Claude CLI recorded for it (a transcript names the model that served a turn but never its 1M-context variant, so VibeSpace commands none) — set one for a specific conversation under Session parameters on its card.": "エイリアスを選ぶか「カスタム…」で特定のモデル ID を入力（例：claude-opus-4-6-20250414）。新規セッションに適用されます。再開した会話は Claude CLI が記録したモデルを保持します（トランスクリプトはターンを処理したモデル名だけを記録し、1M コンテキスト変種を示さないため、VibeSpace は指定しません）— 個別に指定するにはカードの「セッションパラメータ」から。",
  "Default Claude permission mode for new or resumed Claude sessions.": "新規/再開する Claude セッションの既定の権限モード。",
  "Select a level or choose \"Custom...\" to type any value (e.g. xhigh). Applies to NEW sessions: nothing Claude writes records the effort a turn ran at, so a resume commands none and the CLI’s own config decides — set one for a specific conversation under Session parameters on its card.": "レベルを選ぶか「カスタム…」で任意の値を入力（例：xhigh）。新規セッションに適用されます。Claude が書くどの記録にもターンの実行強度は残らないため、再開時は指定せず CLI 自身の設定に従います — 個別に指定するにはカードの「セッションパラメータ」から。",
  "Extra Claude CLI args appended when starting a Claude session.": "Claude セッション起動時に追加する CLI 引数。",
  "Renderer for terminal-mode Claude sessions. \"Fullscreen\" forces the flicker-free alternate-screen renderer with virtualized scrollback (CLAUDE_CODE_NO_FLICKER=1, same as /tui fullscreen); \"Classic\" forces the main-screen renderer; \"Auto\" follows the preference saved by the CLI (/tui). Applies to newly started sessions.": "ターミナルモード Claude セッションのレンダラ。「フルスクリーン」はちらつきのない代替スクリーンレンダラを強制（CLAUDE_CODE_NO_FLICKER=1、/tui fullscreen と同等）；「クラシック」はメインスクリーンレンダラを強制；「自動」は CLI の保存設定（/tui）に従う。新規起動セッションに適用。",
  "Select a known model or choose \"Custom...\" to type a specific model ID. Applies to NEW sessions: a resumed conversation keeps its own value (set one for a specific conversation under Session parameters on its card).": "既知のモデルを選ぶか「カスタム…」で特定のモデル ID を入力。新規セッションに適用されます。再開した会話は自身の値を保持します（個別に指定するにはカードの「セッションパラメータ」から）。",
  "Default Codex permission mode for new or resumed Codex sessions.": "新規/再開する Codex セッションの既定の権限モード。",
  "Default Codex reasoning effort for NEW Codex sessions. A resumed conversation keeps the effort its own last turn ran at; set one for a specific conversation under Session parameters on its card.": "新規 Codex セッションの既定の推論強度。再開した会話は直前のターンで実行された強度を保持します。個別に指定するにはカードの「セッションパラメータ」から。",
  "Extra Codex CLI args appended when starting a Codex session.": "Codex セッション起動時に追加する CLI 引数。",
