  "{n} running {label} conversations started before VibeSpace registered its hooks — Terminate and Resume them to give their agents the VibeSpace tools": "実行中の {label} の会話 {n} 件は VibeSpace が hook を登録する前に開始されました — 終了して再開すると、それぞれの agent が VibeSpace のツールを使えるようになります",
