  "A running conversation keeps the hooks it started with, so its agent has no VibeSpace tools context, task context or bookkeeping until it is restarted.": "実行中の会話は開始時の hook を使い続けるため、再起動するまでその agent には VibeSpace のツール説明、タスクのコンテキスト、記録のリマインドが届きません。",
