  "This subscription isn’t signed in yet — use “Add subscription…” to finish the login first.": "このサブスクはまだサインインしていません——先に「サブスクリプションを追加…」でログインを完了してください。",
  "{name} (subscription)": "{name}（サブスク）",
  "Each session can pick its account (New Session dialog / card ⚙). Subscriptions bill your Pro/Max plan; API keys bill pay-per-use. The starred account is the default when a session doesn’t pick one.": "各セッションでアカウントを選べます（新規セッション / カード ⚙）。サブスクは Pro/Max プラン課金、API キーは従量課金。スター付きのアカウントは、セッションが選ばなかった場合の既定です。",
