  "{n}m": "{n}分",
  "A terminal opened — sign in with the ChatGPT account you want to add. Your other logins are untouched; VibeSpace captures it automatically.": "ターミナルが開きました——追加したい ChatGPT アカウントでサインインしてください。他のログインには影響しません。VibeSpace が自動的に取り込みます。",
  "Add ChatGPT account": "ChatGPT アカウントを追加",
  "Add ChatGPT account…": "ChatGPT アカウントを追加…",
  "CLI login on {host}": "{host} 上の CLI ログイン",
  "ChatGPT / OpenAI accounts": "ChatGPT / OpenAI アカウント",
  "ChatGPT login": "ChatGPT ログイン",
