  "Subagent and workflow-agent requests are billed to the conversation that started them. “Unattributed” is history whose transcript is gone — it is counted, just not named.": "サブエージェントとワークフローエージェントのリクエストは、開始した会話に計上されます。“帰属不明” はトランスクリプトが失われた履歴です。合計には含まれますが、名前を示せません。",
