  "USD per million tokens. Default rates apply to every account (subscriptions bill as this API-equivalent reference). Give an API-key account a discount % or its own rates — different keys really do bill differently.": "単位:百万トークンあたり USD。デフォルト単価は全アカウントに適用されます(サブスクリプションはこの API 等価の参考価格で計算)。API キーのアカウントには割引率や独自単価を設定できます——キーごとに実際の課金は異なります。",
