  "The machine's own CLI login": "このマシン自身の CLI ログイン",
  "same account as “{name}” · a separate sign-in": "「{name}」と同じアカウント · 別々のサインイン",
  "This machine’s CLI login and “{name}” are the same {vendor} account — one quota, usage shown merged — but two separate sign-ins: each expires and is renewed on its own, and signing in one does not sign in the other.": "このマシンの CLI ログインと「{name}」は同じ {vendor} アカウントです — 割り当ては一つで使用量は統合表示されます — が、サインインは別々の二つです。それぞれ個別に期限切れ・更新され、一方にサインインしてももう一方はサインインされません。",
  "same account as this machine’s CLI login — one quota, two separate sign-ins": "このマシンの CLI ログインと同じアカウント — 割り当ては一つ、サインインは別々の二つ",
