  "Handled — mark done": "対応済み — 完了にする",
  "Items waiting on you": "あなたの対応待ちの項目",
  "Nothing needs you right now. Agents file items here with vibespace-ask when they need a decision or input.": "現在あなたの対応が必要な項目はありません。エージェントは判断や入力が必要になると vibespace-ask でここに項目を登録します。",
  "Nothing waiting on you": "対応待ちの項目はありません",
