  "Reopen": "再オープン",
  "Session not found in the list yet — try from the sidebar": "セッションがまだ一覧にありません — サイドバーから開いてください",
  "Show the \"For you\" inbox": "「あなた宛て」受信箱を表示",
  "Show the inbox of items agents filed for you (decisions/input needed) in the taskbar": "エージェントがあなた宛てに登録した項目(判断・入力が必要)の受信箱をタスクバーに表示",
  "This session is running outside VibeSpace": "このセッションは VibeSpace の外で実行されています",
  "all clear": "すべて対応済み",
  "by the agent": "エージェントによる",
  "automatically": "自動的に",
  "dismissed": "無視済み",
  "{h}h ago": "{h}時間前",
  "{n} open": "{n} 件未対応",
  "Prompt cache hit rate (last turn): {pct}% of input tokens were read from cache ({read} of {total}). Higher = cheaper + faster.": "プロンプトキャッシュのヒット率（直前のターン）：入力トークンの {pct}% がキャッシュから読み込まれました（{total} 中 {read}）。高いほど安く高速です。",
  "Editing below — Save & Close to hand the file back": "下のペインで編集中 — 保存して閉じるとファイルがエージェントに戻ります",
  "Waiting for the editor below": "下のエディタの完了待ち",
  "The terminal resumes after Save & Close.": "保存して閉じるとターミナルが再開します。",
  "detail": "詳細",
  "Model-scoped data comes from the ⟳ refresh, not the passive feed": "モデル別クォータは ⟳ 手動更新から取得（パッシブ収集には含まれません）",
  "Model-scoped weekly limits (e.g. Fable) aren’t in the passive feed — ⟳ fetches them on demand": "モデル別の週次上限（Fable など）はパッシブ収集に含まれません — ⟳ でオンデマンド取得",
  "Refresh from Anthropic now (also fetches model-scoped limits like Fable) — user-initiated, min 60s apart": "Anthropic から今すぐ更新（Fable などモデル別上限も取得）— ユーザー操作時のみ、最短 60 秒間隔",
  "as of {ago}": "{ago}時点",
  "API billing (pay per use)": "API 課金（従量制）",
  "estimated from the login state at spawn": "起動時のログイン状態から推定",
  "Billing identity unknown (started before tracking)": "課金元不明（トラッキング開始前に起動）",
  "ChatGPT account": "ChatGPT アカウント",
