  "Inbox": "受信箱",
  "Notifications": "通知",
  "No notifications yet.": "まだ通知はありません。",
  "Notification popup duration (seconds)": "通知ポップアップの表示時間（秒）",
  "How long toast cards (new inbox items, errors, confirmations) stay on screen. They appear next to the inbox button and every one is kept in the inbox popup’s Notifications tab.": "トーストカード（新着受信箱アイテム、エラー、確認）が画面に表示される時間。受信箱ボタンの横に表示され、すべて受信箱ポップアップの「通知」タブに保存されます。",
  "Update VibeSpace": "VibeSpace を更新",
  "Checking for updates…": "更新を確認中…",
  "Update now": "今すぐ更新",
  "Latest version": "最新バージョン",
  "Active": "実行中",
  "No running sessions": "実行中のセッションはありません",
