  "The desktop stream is reconnecting — your text is pasted when it is back": "デスクトップのストリームを再接続中です — 戻ったらテキストを貼り付けます",
  "Not pasted — the desktop did not come back within 30 s; press Reconnect": "貼り付けていません — デスクトップが 30 秒以内に戻りませんでした。「再接続」を押してください",
  "Reconnecting {n}/{total}…": "再接続中 {n}/{total}…",
  "This page cannot read your clipboard — paste into the box under the bar, then Send": "このページはクリップボードを読めません — バーの下のボックスに貼り付けて「送信」を押してください",
  "The browser refused clipboard access — paste into the box under the bar, then Send": "ブラウザがクリップボードへのアクセスを拒否しました — バーの下のボックスに貼り付けて「送信」を押してください",
  "The browser is still asking for clipboard permission — answer it, or paste into the box under the bar": "ブラウザがまだクリップボードの許可を求めています — 応答するか、バーの下のボックスに貼り付けてください",
  "Your clipboard holds no text — paste into the box under the bar, then Send": "クリップボードにテキストがありません — バーの下のボックスに貼り付けて「送信」を押してください",
  "The browser is still asking for clipboard permission — answer it, or paste here (Ctrl+V), then Send.": "ブラウザがまだクリップボードの許可を求めています — 応答するか、ここに貼り付けて（Ctrl+V）「送信」を押してください。",
