  "{provider} re-authorized": "{provider} を再認可しました",
  "{provider} reported the saved sign-in as expired or revoked. Sign in again to mint a fresh token — nothing else about the mount changes.": "保存されたサインインは期限切れまたは取り消されたと {provider} が報告しました。再サインインして新しいトークンを取得してください — マウントの他の設定は変わりません。",
