  "Parse failed": "解析に失敗しました",
  "Passed to the underlying transfer engine (rclone) — custom API keys, tuning, provider quirks. See rclone.org/docs.": "下層の転送エンジン (rclone) に渡されます——カスタム API キー、チューニング等。rclone.org/docs 参照。",
  "Password (if no key)": "パスワード（鍵がない場合）",
  "Password / app token": "パスワード / アプリトークン",
  "Paste the contents of your rclone.conf (from `rclone config file` — usually ~/.config/rclone/rclone.conf). Every remote inside it becomes a mount you can pick.": "rclone.conf の内容を貼り付けてください（`rclone config file` で場所確認——通常 ~/.config/rclone/rclone.conf）。中の各リモートが選択可能なマウントになります。",
  "Paste the share link": "共有リンクを貼り付けてください",
  "Path within the remote (optional)": "リモート内パス（任意）",
  "Pick at least one remote.": "少なくとも 1 つ選択してください。",
