  "Share a folder from “{name}”": "「{name}」からフォルダを共有",
  "Share a folder from “{name}” (direct)": "「{name}」からフォルダを共有（直結）",
  "Share imported": "共有をインポートしました",
  "Share link": "共有リンク",
  "Share link — treat it like a key; send over company chat only": "共有リンク——鍵として扱い、社内チャットのみで送付してください",
  "Share name": "共有名",
