  "no listening TCP ports found": "待ち受け中の TCP ポートは見つかりません",
  "forwarded": "転送済み",
  "directory on this machine…": "このマシン上のディレクトリ…",
  "Publish public": "公開する",
  "Stop public": "公開を停止",
  "Make a public internet URL via the relay (shareable preview link)": "リレー経由で公開 URL を作成（共有可能なプレビューリンク）",
  "Stop sharing publicly": "公開共有を停止",
  "Public URL removed": "公開 URL を削除しました",
