  "Kill this orphaned process": "この孤児プロセスを終了",
  "Orphaned process killed": "孤児プロセスを終了しました",
  "Kill": "終了",
  "Orphaned dev server: {ports} — its working directory was deleted; the Ports panel can kill it": "孤児dev server検出: {ports}——作業ディレクトリは削除済み。ポートパネルで終了できます",
  "More actions": "その他の操作",
  "Add account…": "アカウントを追加…",
  "Keep the rail when the sidebar is collapsed": "サイドバー折りたたみ時もレールを維持",
  "vscode behavior: collapsing the sidebar leaves the 44px icon rail on screen — click any icon to expand back. Off = collapsing hides everything.": "vscode方式：折りたたみ後も44pxのアイコンレールが残り、クリックで再展開。オフなら全て隠れます。",
  "Public URLs need the frp relay — not configured on this instance": "公開URLにはfrpリレーが必要——このインスタンスでは未設定",
  "+ {n} system listeners": "+ {n} 件のシステムリスナー",
  "Activity rail (vscode-style)": "アクティビティレール（vscode風）",
  "A vertical icon rail on the sidebar edge hosting the session panels (Folders / Task Groups / Remote / Ports) plus Agents, Plugins and quick launchers. Turn off to restore the classic tab bar and keep Agents/Plugins as dialogs.": "サイドバー端の縦型アイコンレール。セッションパネル（フォルダ/タスクグループ/リモート/ポート）と Agents・プラグイン・ランチャーを収容。オフでクラシックなタブバーに戻ります。",
  "Ports": "ポート",
