  "window reset since last reading": "前回取得後にウィンドウがリセット",
  "Dead-reckoned estimate: last confirmed reading + your local usage since, at learned rates. ⟳ fetches a fresh reading to re-calibrate.": "推測航法による推定：最後の実測値にその後のローカル使用量を学習レートで加算（破線部分）。⟳ で実測値を取得して補正します。",
  "Pooled account — one billing identity auto-switching across your subscriptions": "プールアカウント — 1つの請求アイデンティティがサブスクリプション間を自動切替",

  // ── i18n coverage sweep (missing-key fill, added post-2.265.0 fix campaign) ──
  "\"{name}\" already exists here": "「{name}」はここに既に存在します",
  "\"{name}\" installed — waiting for it to dial in": "「{name}」をインストールしました——ダイヤルイン待ち",
  "\"{name}\" is still loading — {host} may be slow. Leave the window open.": "「{name}」はまだ読み込み中です——{host} の応答が遅い可能性があります。このウィンドウを開いたままにしてください。",
  "\"{name}\" upgraded — dial link is live": "「{name}」をアップグレードしました——接続リンクが有効です",
  "(unconfirmed — {host} hasn’t answered the availability check yet)": "（未確認——{host} はまだ利用可否チェックに応答していません）",
  "API": "API",
  "About to {what}. Terminating kills the running agent process.": "{what}を実行しようとしています。終了すると実行中の agent プロセスが強制終了されます。",
  "Advanced: you can also paste the JSON from `rclone authorize \"<provider>\"` run elsewhere.": "上級：別の場所で実行した `rclone authorize \"<provider>\"` の JSON を貼り付けることもできます。",
  "After nudging a session once, wait at least this long before nudging it again. 0 = no cooldown.": "一度セッションに催促した後、次に催促するまで最低これだけの時間を空けます。0 = クールダウンなし。",
  "Agent transcript could not be loaded.": "エージェントのトランスクリプトを読み込めませんでした。",
  "Already connecting…": "接続処理中…",
  "Already running — opened the live session instead": "すでに実行中です——代わりに実行中のセッションを開きました",
  "Apply batch actions": "一括操作を適用",
  "Attaching \"{name}\" is taking unusually long — it may still be working; check the connection before reloading": "「{name}」への接続に時間がかかっています — まだ動作している可能性があります。再読み込みの前に接続を確認してください",
  "Availability below is unconfirmed until the machine answers.": "マシンが応答するまで、下記の利用可否は未確認です。",
  "Bookmark change not saved: {msg}": "ブックマークの変更を保存できませんでした：{msg}",
  "ChatGPT": "ChatGPT",
  "ChatGPT (Codex)": "ChatGPT (Codex)",
  "Checking the connection…": "接続を確認中…",
  "Claude": "Claude",
  "Click ⟳ to re-scan this host.": "⟳ をクリックしてこのホストを再スキャン。",
  "Codex": "Codex",
  "Complete this account’s login in Manage agents first.": "先に Manage agents でこのアカウントのログインを完了してください。",
  "Connecting to {host}…": "{host} に接続中…",
  "Connection lost before the goal was set — your command was restored to the input": "目標を設定する前に接続が失われました——入力内容は入力欄に復元されました",
  "Could not change the default account — {reason}": "既定のアカウントを変更できませんでした — {reason}",
  "Could not check the integration on {host} — {reason}": "{host} での連携状態を確認できませんでした — {reason}",
  "Could not load plugins — the server did not answer.": "プラグインを読み込めませんでした——サーバーが応答しませんでした。",
  "Could not load usage: {msg}": "使用状況を読み込めませんでした：{msg}",
  "Could not read the hook status — {reason}": "フックの状態を読み取れませんでした — {reason}",
  "Could not remove the account — {reason}": "アカウントを削除できませんでした — {reason}",
  "Could not remove the grid preset — {reason}": "グリッドプリセットを削除できませんでした — {reason}",
  "Could not save the email — {reason}": "メールアドレスを保存できませんでした — {reason}",
  "Could not save the grid preset — {reason}": "グリッドプリセットを保存できませんでした — {reason}",
  "Could not save the note — {reason}": "メモを保存できませんでした — {reason}",
  "Couldn't jump there — the conversation history could not be read": "そこへジャンプできませんでした——会話履歴を読み取れませんでした",
  "Couldn't load earlier messages": "それより前のメッセージを読み込めませんでした",
  "Couldn't load messages received while offline": "オフライン中に受信したメッセージを読み込めませんでした",
