  "the connection did not come up — hover the row’s status dot for details": "接続が確立されませんでした——詳細はその行のステータスドットにカーソルを合わせて確認してください",
  "the machine": "そのマシン",
  "the server did not answer": "サーバーが応答しませんでした",
