  "OpenCode": "OpenCode",
  "Build": "ビルド",
  "A model id the agent offers (provider/model, e.g. opencode/big-pickle) — the list fills from the agent once a session has started; empty keeps the agent default. Applies to NEW sessions: a resumed conversation keeps the model OpenCode’s own session record names (that needs the OpenCode background service; without it the default applies and the server log says which rung it used).": "エージェントが提供するモデル id（provider/model、例: opencode/big-pickle）。リストは最初のセッション開始後にエージェントから取得されます。空欄ならエージェントの既定値。新規セッションに適用されます：再開した会話は OpenCode 自身のセッション記録が示すモデルを保持します（OpenCode バックグラウンドサービスが必要。なければ既定値が適用され、サーバーログにその旨が出ます）。",
  "Default OpenCode session mode for new sessions: build executes tools per its permission rules, plan disallows edits.": "新しい OpenCode セッションの既定モード: build は権限ルールに従ってツールを実行し、plan は編集を禁止します。",
  "Extra OpenCode CLI args appended when starting an OpenCode session.": "OpenCode セッション起動時に追加する CLI 引数。",
