  "Installed from {source}: {value}": "インストール元 {source}: {value}",
  "a folder under data/plugins/<id>/ with vibespace-plugin.json — see docs/plugins.md": "data/plugins/<id>/ 配下の vibespace-plugin.json を持つフォルダ — docs/plugins.md 参照",
  "No plugins installed. Use Install plugin… (a folder, a git URL, a .vsp file or a GitHub release) — docs/examples/hello-plugin is the smallest complete one.": "プラグインは未インストールです。「プラグインをインストール…」（フォルダ、git URL、.vsp ファイル、GitHub リリース）を使ってください — docs/examples/hello-plugin が最小の完全な例です。",
