  "Uninstall \"{name}\"? Its folder and data move to data/plugins-trash (nothing is deleted).": "「{name}」をアンインストールしますか？フォルダとデータは data/plugins-trash へ移動します（何も削除されません）。",
  "Uninstalled {id} (moved to trash)": "{id} をアンインストールしました（ゴミ箱へ移動）",
  "Capabilities of {name}": "{name} の権限",
  "Enable \"{name}\" (trusted)?": "「{name}」を信頼して有効化しますか？",
  "This plugin declares:": "このプラグインの宣言:",
  "This plugin asks for more than the sandbox gives. Enable it only if you trust its author:": "このプラグインはサンドボックスを超える権限を求めています。作者を信頼できる場合のみ有効化してください:",
  "Trusted code has the same power as VibeSpace itself. There is no undo beyond disabling it.": "信頼済みコードは VibeSpace 自体と同じ権限を持ちます。無効化する以外に取り消す方法はありません。",
  "Trusted since {when}": "{when} から信頼済み",
