  "Inject every queued message into the running turn, in order": "キュー内のすべてのメッセージを順番に現在のターンへ投入します",
  "{n} queued — runs after this turn": "{n} 件キュー待ち —— このターンの後に実行",
  "Waiting behind the running turn — steering it injects it now, at the agent’s next reply": "実行中のターンの後ろで待機中 —— 投入するとエージェントは次の返信時に読みます",
  "Injected into the running turn": "実行中のターンに投入済み",
  "Removed from the queue — it will not run": "キューから削除 —— 実行されません",
  "That message is no longer queued — it already ran.": "そのメッセージはもうキューにありません —— すでに実行されました。",
  // the Alt+Enter chord (2026-09-07)
  "Enter queues": "Enter でキュー",
  "Alt+Enter injects now": "Alt+Enter で即時投入",
  "Send now — inject into the running turn": "今すぐ送信 —— 実行中のターンに投入",
  "Sending during a turn": "ターン実行中の送信",
  "Enter queues it — it runs after this turn": "Enter でキュー —— このターンの後に実行",
  "Alt+Enter injects it into the running turn (the agent sees it at its next reply)": "Alt+Enter で実行中のターンに投入（エージェントは次の返信時に読みます）",
  "Sent — but it could not be injected into the running turn; it will run when the turn ends.": "送信しました —— ただし実行中のターンには投入できませんでした。このターンの終了後に実行されます。",
  'agent default': 'エージェント既定',
  'Response style': '応答スタイル',
  'Response style: {v} — set at spawn; a change applies on the next resume': '応答スタイル：{v} — 起動時に設定。変更は次回 resume から有効',
  'Response style: the agent default — click to pick (applies on the next resume)': '応答スタイル：エージェント既定 — クリックで選択（次回 resume から有効）',
  'Response style: {v} — click to change it right now (applies from the next turn)': '応答スタイル：{v} — クリックで今すぐ変更できます（次のターンから有効）',
  'Response style: whatever this agent’s own config says — click to pick one (applies from the next turn)': '応答スタイル：このエージェント自身の設定に従います — クリックで選択（次のターンから有効）',
  'Response style “{v}” is saved and applies on the next resume (now running: {cur})': '応答スタイル「{v}」を保存しました。次回 resume から有効（現在：{cur}）',
  'Response style “{v}” applies on the next resume': '応答スタイル「{v}」は次回 resume から有効です',
  'Response style cleared — applies on the next resume': '応答スタイルを解除しました — 次回 resume から有効',
  'Response style “{v}” applies from the next turn': '応答スタイル「{v}」は次のターンから有効です',
  'Response style cleared — the agent’s own config applies again': '応答スタイルを解除しました — エージェント自身の設定に戻ります',
  'This agent applies a style change to the running session, from its next turn.': 'このエージェントは実行中のセッションにもスタイル変更を適用します（次のターンから）。',
  '(saved: {v} — applies on the next resume)': '（保存済み：{v} — 次回 resume から有効）',
  'your choice for this session': 'このセッションでの手動選択',
  'Task-Group default': 'タスクグループ既定',
  'instance default': 'インスタンス既定',
  'harness default — the agent’s own config decides': 'エージェント既定 — 本体の設定に従います',
  'lead with results, skip preamble': '結論から。前置きを省く',
  'explain choices and patterns': '選択理由とパターンを説明',
  'teach while doing': '作業しながら教える',
  'act first, minimize interruptions': 'まず動く。中断を最小化',
  'warmer, more conversational': 'より親しみやすい会話調',
  'terse and task-focused': '簡潔でタスク中心',
  'Default response style (Codex)': '既定の応答スタイル（Codex）',
  'The personality new Codex chat sessions start with. Blank = leave it to your own ~/.codex/config.toml (this is the default; VibeSpace used to force "pragmatic" on every session). Unlike Claude, a running Codex session CAN be re-styled from the chat status bar — it applies from the next turn.': '新しい Codex チャットセッションが使う personality。空欄 = 自分の ~/.codex/config.toml に任せる（これが既定。以前の VibeSpace は全セッションに "pragmatic" を強制していました）。Claude と違い、実行中の Codex セッションはチャットステータスバーから変更でき、次のターンから有効になります。',
  'Generated image': '生成した画像',
  'Prompt': 'プロンプト',
  'Sleeping': 'スリープ中',
  'remaining': '残り',
  'Slept': 'スリープしました',
  'Response style “{v}” is saved for this conversation — the agent is still on {cur}; pick it again to apply it now': '応答スタイル「{v}」をこの会話に保存しました — agent は現在 {cur} のままです。もう一度選ぶとすぐ適用されます',
  'This session’s agent started before live style switching — restart it to apply a change.': 'このセッションの agent はライブ変更対応前に起動しています — 適用には再起動が必要です。',
  'what this session started with': 'このセッションの起動時の値',
