  "No conversations discovered yet.": "まだ会話は見つかっていません。",
  "This message has no vendor id — the adapter minted a stable key from its content.": "このメッセージにはベンダー ID がありません —— アダプタが内容から安定したキーを生成しました。",
  "This conversation is not available.": "この会話は現在利用できません。",
  "Read-only here ({why})": "ここは読み取り専用です({why})",
  "No messages yet.": "まだメッセージはありません。",
  "The recipient sees this as sent by the app, not by you.": "受信者にはアプリからの送信として表示され、あなた本人としては表示されません。",
  "It is not verified whose name the recipient sees on this message.": "このメッセージで受信者に誰の名前が表示されるかは未検証です。",
  "not scanning": "スキャンなし",
  "not polling": "ポーリングなし",
