  "Show the shared-desktop (VNC) button in the toolbar (hidden anyway when this machine has no VNC server)": "ツールバーに共有デスクトップ（VNC）ボタンを表示します（このマシンに VNC サーバーがない場合はいずれにせよ表示されません）",
  "Show the desktop-application launcher button in the toolbar (hidden anyway when this machine has no display backend)": "ツールバーにデスクトップアプリ起動ボタンを表示（このマシンに画面バックエンドがない場合はいずれにせよ非表示）",
  "Starting application…": "アプリケーションを起動中…",
  "Stop this application and its display": "このアプリケーションとその画面を停止",
  "This app will keep running until you stop it": "このアプリは停止するまで実行し続けます",
  "This desktop app no longer exists": "このデスクトップアプリはもう存在しません",
  "Type a command to run": "実行するコマンドを入力してください",
  "Windows will use {backend}": "ウィンドウは {backend} を使用します",
  "Windows will use {backend} — {why}": "ウィンドウは {backend} を使用します —— {why}",
  "idle stop in under a minute": "1 分未満でアイドル停止",
  "idle stop in {n} min": "{n} 分後にアイドル停止",
  "fixed {geometry} ({by}) — install tigervnc for a window that follows": "固定 {geometry}（{by}）— ウィンドウ追従には tigervnc をインストール",
  "fixed display ({by}) — install tigervnc for a window that follows": "固定ディスプレイ（{by}）— ウィンドウ追従には tigervnc をインストール",
  "This rung’s display cannot resize: the app is fitted to the fixed framebuffer and scaled in the browser. With TigerVNC (Xvnc) the display follows the window.": "この段のディスプレイはサイズ変更できません：アプリは固定フレームバッファに合わせられ、ブラウザ側で拡縮されます。TigerVNC（Xvnc）ならディスプレイがウィンドウに追従します。",
  "not on PATH": "PATH にありません",
  "starting": "起動中",
  "Browsers": "ブラウザ",
  "This is your own browser window (an app); the Agent browser is separate": "これはあなた自身のブラウザウィンドウ（アプリ）です。エージェントブラウザとは別物です",
  "Open URL (optional)": "開く URL（任意）",
  "Keep the profile after it closes": "終了後もプロファイルを残す",
  "Snap: cannot reach the data folder": "Snap 版: データフォルダーに届かない",
  "No private profile folder here": "ここでは専用プロファイルを置けない",
  "Open URL must be an http:// or https:// address": "開く URL は http:// または https:// のアドレスにしてください",
  "Advanced: run any command": "詳細: 任意のコマンドを実行",
  "No known applications were found on this machine — use “Advanced” below to run any program.": "このマシンに既知のアプリが見つかりません — 下の「詳細」から任意のプログラムを実行できます。",
  "Launching…": "起動しています…",
  "{n} running": "{n} 件実行中",
  "{used} of {cap} slots in use": "{cap} スロット中 {used} 使用中",
  "0 (the default) never stops an app for sitting still. Set minutes to stop a desktop application window that had no input for that long; \"Keep running\" in a window exempts that app.": "0（既定）では放置中のアプリを停止しません。分数を設定すると、その時間入力のないデスクトップアプリのウィンドウを停止します。ウィンドウの「実行を維持」でそのアプリを除外できます。",
  "Archive finished tasks after (hours)": "完了したタスクをアーカイブするまでの時間（時間）",
  "A one-shot task that finished successfully leaves the Background Work list for the archive this many hours after it ended (its runs, delivery log and acknowledgement are kept; poll/show of the id still answer). 0 = never archive finished tasks.": "正常に完了した単発タスクは、終了からこの時間が経つとバックグラウンド作業の一覧からアーカイブへ移ります（実行履歴・配信ログ・確認状態は保持され、その id への poll/show は引き続き応答します）。0 = 完了タスクをアーカイブしない。",
  "Archive acknowledged failures after (days)": "確認済みの失敗をアーカイブするまでの日数（日）",
  "A failed, missed, interrupted or unverified one-shot leaves the list this many days after somebody ACKNOWLEDGED it (its owner conversation was notified, an owner agent polled it, or you expanded its row). An unacknowledged failure is never archived. 0 = never archive failures.": "失敗・見逃し・中断・未検証の単発タスクは、誰かが確認してから（所有する会話に通知が届いた、所有エージェントがポーリングした、またはあなたがその行を展開した）この日数が経つと一覧から外れます。未確認の失敗はアーカイブされません。0 = 失敗をアーカイブしない。",
  "seen": "確認済み",
  "held": "保留中",
  "created by you": "あなたが作成",
  "session {id} (no longer listed)": "セッション {id}（一覧にありません）",
  "1 notification held": "1 件の通知を保留中",
  "{n} notifications held": "{n} 件の通知を保留中",
