  "Outbox: a message with a link always needs your approval": "送信箱: リンクを含むメッセージは常に承認が必要",
  "Outbox: a message with an attachment always needs your approval": "送信箱: 添付を含むメッセージは常に承認が必要",
  "Outbox: working hours end (HH:MM)": "送信箱: 勤務時間の終了(HH:MM)",
