  "Sent directly: the channel policy is \"direct\" and no guard applied.": "直接送信しました: このチャンネルのポリシーは「直接送信」で、ガードは作動しませんでした。",
  "The outbox is not available.": "送信箱は利用できません。",
  "This send is never retried automatically. Check the conversation on the platform before proposing it again.": "この送信は自動では再試行されません。再提案する前にプラットフォーム上の会話を確認してください。",
  "Who can see this conversation": "この会話を見られるのは",
  "Why: {ref}": "きっかけ: {ref}",
  "Will send as {who}": "{who} として送信します",
  "Just appeared or moved — read it first, then decide": "表示されたばかり、または移動したばかりです — まず読んでから決めてください",
  "An invisible character that changes how the text reads — it is sent as it is": "文字の表示のされ方を変える不可視の文字です — そのまま送信されます",
  "In reply to": "返信先",
  "To": "宛先",
  "Cc": "Cc",
  "Subject": "件名",
  "New message": "新規メッセージ",
  "The text carries invisible characters that change how it reads ({list}) — each is shown as a mark and is sent as it is": "本文に読み方を変える不可視の文字が含まれています({list}) — それぞれ記号として表示し、そのまま送信されます",
  "This proposal changed since the card was drawn — nothing was sent; read it again, then decide": "カードの表示後にこの提案が変わりました — 何も送信されていません。もう一度読んでから決めてください",
  "the message this reply answers is no longer a stored message of this conversation — nothing was sent": "この返信が答えるメッセージは、もうこの会話に保存されたメッセージではありません — 何も送信されていません",
  "this reply was proposed before its recipients were resolved — ask the agent to propose it again": "この返信は宛先が確定する前に提案されました — エージェントにもう一度提案してもらってください",
