  "{a} awaiting your approval · {n} proposals": "{a} 件が承認待ち · 提案 {n} 件",
  "{n} to approve": "{n} 件承認待ち",
  "{who} asks: {why}": "{who} の要求: {why}",
  "sending needs the send permission on the connected app — reconnect (Re-authorize) to allow drafts and sending; on Lark that also means enabling im:message + im:message.send_as_user and publishing a version": "送信には接続済みアプリの送信権限が必要です — 再接続(再認可)して下書きと送信を許可してください。Lark では im:message + im:message.send_as_user を有効にしてバージョンを公開する必要もあります",
  "this channel is read-only": "このチャンネルは読み取り専用です",
