  "on": "オン",
  "off": "オフ",
  "(instance default)": "(インスタンス既定)",
  "When on, a message an AGENT drafted goes out with one trailing line naming the agent. Your own drafts never get one. The approval card says who the recipient will see either way.": "オンにすると、AGENT が下書きしたメッセージの末尾にその agent 名を記す一行が付きます。あなた自身の下書きには付きません。いずれにせよ承認カードは受信者が誰を見るかを示します。",
  "Use instance default": "インスタンス既定を使う",
  "Last real send was attributed by the platform to {who} ({when})": "直近の実送信はプラットフォーム上で {who} として扱われました ({when})",
  "the user": "ユーザー本人",
  "an app / bot": "アプリ / ボット",
  "this channel's identity declaration is still unverified in code; this measurement is what settles it": "このチャンネルの ID 宣言はコード上まだ未検証です。この測定が確定させます",
  "Outbox: append a \"drafted by <agent>\" line to messages an agent drafted": "送信箱: エージェントが下書きしたメッセージに「<agent> が下書き」の一行を付ける",
  "OFF (recommended): a message goes out exactly as you approved it. ON: an agent-drafted message ends with one line naming the drafting agent. Your own drafts never get one. Each channel can override this in the Channels panel. Either way the approval card and the receipt say who the recipient will see.": "オフ(推奨): メッセージは承認したとおりに送られます。オン: エージェントが下書きしたメッセージの末尾にそのエージェント名を記す一行が付きます。あなた自身の下書きには付きません。チャンネルごとにチャンネルパネルで上書きできます。いずれにせよ承認カードと受領書は受信者が誰を見るかを示します。",
  "Quota refreshed via {rung} — identity not verified: {why}": "{rung}経由でクォータを更新 — 本人性は未検証: {why}",
  "a live session": "稼働中のセッション",
  "this account’s own /usage panel": "このアカウント自身の /usage パネル",
  "Refreshed via {rung} · identity verified": "{rung}経由で更新 · 本人性を検証済み",
  "Refreshed via {rung} · identity not verified": "{rung}経由で更新 · 本人性は未検証",
  "identity not verified": "本人性は未検証",
  "Extra usage is enabled on this org: requests past 100 % are billed pay-per-use. The pool moves conversations onto it only when no member has quota left.": "この組織では追加利用(usage credits)が有効です: 100 % を超えたリクエストは従量課金されます。プールは他のどのメンバーにもクォータが残っていない場合にのみ会話をここへ移します。",
  "Credits": "従量",
  "Using paid overage credits — this account’s subscription quota is spent and its requests are billed pay-per-use.": "有料の超過クレジットを使用中 — このアカウントのサブスクリプション枠は使い切られ、リクエストは従量課金されています。",
  "Spent this period: {money}.": "今期の支出: {money}。",
