  "Search this conversation": "この会話を検索",
  "Copy text": "テキストをコピー",
  "\"@{token}\" is not a member of this group — pick one from the @ list (a literal @word goes in backticks)": "「@{token}」はこのグループのメンバーではありません — @ リストから選んでください（文字どおりの @語 はバッククォートで囲みます）",
  "\"@{token}\" names several members — pick the one you mean from the @ list": "「@{token}」に当てはまるメンバーが複数います — @ リストから目的のメンバーを選んでください",
  "Open this agent's conversation": "このエージェントの会話を開く",
  "Fork from here": "ここから分岐",
  "Message details": "メッセージの詳細",
  "Show or hide bookmarks": "ブックマークの表示／非表示",
  "{n} selected": "{n} 件選択中",
  "Select…": "選択…",
  "Agent session": "エージェントセッション",
  "Add desktop": "デスクトップを追加",
  "No windows on this desktop": "このデスクトップにウィンドウはありません",
  "Minimized": "最小化済み",
  "Copy screen (the visible terminal text)": "画面をコピー（ターミナルの表示中テキスト）",
  "Nothing on screen to copy": "画面にコピーできる内容がありません",
  "Copied {n} lines": "{n} 行をコピーしました",
  // ── Communication panel a3 i18n (2026-09-18): the codes the server sends, worded; the adapters' and the registry's declared keys ──
  "policy::direct": "直接送信",
  "policy::review": "承認",
  "connected — this instance": "接続済み — このインスタンス",
  "The keys stored for this row cannot be decrypted with the current key file — restore the key file this instance had when they were entered, or clear the keys and enter them again.": "この行に保存されたキーは現在のキーファイルでは復号できません — 入力時にこのインスタンスが持っていたキーファイルを復元するか、キーを消去して入力し直してください。",
  "Used by this instance": "このインスタンスで使用中",
