  "The cluster provides no preset by that name": "クラスターにはその名前のプリセットがありません",
  "There is no cluster default for this row": "この行にはクラスターのデフォルトがありません",
  "Nothing can test this row yet — its consumer is not wired in": "この行はまだテストできません — 利用側が接続されていません",
  "This row declares a test but nothing runs it": "この行はテストを宣言していますが、実行するものがありません",
  "The integrations store could not be read — every write is refused until it can be": "連携ストアを読めません — 読めるようになるまで書き込みはすべて拒否されます",
  "The secret key file could not be read": "秘密鍵ファイルを読めません",
  "the login expired": "ログインの期限切れ",
  "the refresh token expired": "リフレッシュトークンの期限切れ",
