  "Delete {name} permanently?": "{name} を完全に削除しますか?",
  "This removes the set-aside directory for good — its cookies and logins with it. There is no undo.": "脇に置いたディレクトリを Cookie とログイン状態ごと完全に削除します。元に戻せません。",
