  "Unregistered directories": "未登録のディレクトリ",
  "under {base} — a Chromium profile no record names; adopt the ones worth keeping, set the rest aside": "{base} 配下 — どのレコードも指していない Chromium プロファイル。残す価値のあるものは引き取り、残りは脇に置いてください",
  "None — every profile directory here is named by a record.": "なし — ここにあるプロファイルディレクトリはすべてレコードが指しています。",
