  "{label} — agent window": "{label} — エージェントウィンドウ",
  'Desktop app display backend order': 'デスクトップアプリの表示バックエンド順',
  'Comma-separated rung ids that reorder the picture-backend ladder for NEW desktop apps on this instance, e.g. "vnc-display, xpra" to keep the whole-display rung first. Empty = installed order (xpra > vnc-display > desktop-singleton). Unknown ids are ignored; a running app keeps the backend it started with.': 'カンマ区切りのバックエンド id で、このインスタンスの新規デスクトップアプリの画面バックエンドの優先順を並べ替えます（例: "vnc-display, xpra" で全画面方式を優先）。空 = インストール順（xpra > vnc-display > desktop-singleton）。不明な id は無視され、実行中のアプリは起動時のバックエンドを保ちます。',
  'Keyboard input for the application': 'アプリケーションへのキーボード入力',
  'Active on another client': '別のクライアントで使用中',
  'Resume here': 'ここで再開',
  'Make this window the active one — the other client is blocked until it resumes': 'このウィンドウをアクティブにします — もう一方のクライアントは再開するまでブロックされます',
  'Could not resume here': 'ここで再開できませんでした',
  'Copied in the app — click to copy': 'アプリ内でコピーされました — クリックしてコピー',
  'The application put text on its clipboard; this page cannot write yours without a click (plain http)': 'アプリケーションがそのクリップボードにテキストを置きました。平文 http ではクリックなしにあなたのクリップボードへ書き込めません',
  'Copied to your clipboard': 'クリップボードにコピーしました',
  'Could not copy — select the text in the app and press Ctrl+C again': 'コピーできませんでした — アプリ内でテキストを選択してもう一度 Ctrl+C を押してください',
  'The application closed its window': 'アプリケーションがウィンドウを閉じました',
  'The application is not connected': 'アプリケーションは接続されていません',
  'Pasted into the application': 'アプリケーションに貼り付けました',
  'Waiting for the application window…': 'アプリケーションのウィンドウを待っています…',
  "Priority": "優先度",
  "High priority": "高優先度",
  "Low priority": "低優先度",
  "Backlog cleanup nudge: items per session": "バックログ整理ナッジ：セッションあたりの項目数",
  "When one session holds this many open backlog items (claimed or parked by it), its backlog commands and its per-turn backlog note ask it to finish, drop or merge items before parking more. 0 = never.": "1 つのセッションが（自分で引き受けた、または保留した）未解決のバックログ項目をこの数だけ抱えると、そのバックログコマンドとターンごとのバックログ通知が、新しく保留する前に項目の完了・破棄・統合を求めます。0 = 通知しない。",
  "Scaled to fit — the app needs at least {w}×{h}": "収まるように縮小 — アプリには少なくとも {w}×{h} が必要です",
  "The scale this app was started at (Settings → Desktop app scale). A change takes effect when the app is launched again.": "このアプリを起動したときのスケール（設定 → デスクトップアプリのスケール）。変更はアプリを再起動したときに反映されます。",
  "xpra streams each app window as pixels; text stays crisp at your screen’s scale": "xpra は各アプリウィンドウをピクセルとして配信します。文字は画面のスケールで描かれ、くっきり表示されます",
  "Auto (this screen)": "自動（この画面）",
