  "For you · reply to #{id}": "あなた宛て · #{id} への返信",
  "Not from an agent session — nothing to reply to": "エージェントセッションからではありません — 返信先がありません",
  "Background Work item — answer it in the job panel": "Background Work の項目 — ジョブパネルで回答してください",
  "Answer it on the helper’s card — click the item to go there": "ヘルパーのカードで回答してください — この項目をクリックすると移動します",
  "{n} items from this agent": "このエージェントからの項目 {n} 件",
  "Inbox for this session": "このセッションの受信箱",
  "{n} more…": "ほか {n} 件…",
  "Could not update {n} items: {why}": "{n} 件を更新できませんでした：{why}",
  "Dismiss every open ask of this agent (↺ reopens)": "このエージェントの未対応の項目をすべて却下（↺ で再オープン）",
  "Login expiry": "ログイン期限",
  "Account pool": "アカウントプール",
  "Notices by source": "通知を発信元で絞り込む",
  "Show all notices": "すべての通知を表示",
