  "No groups yet. \"New group\" starts one with live agent sessions; an agent can too (vibespace-msg group create). Every conversation of an account you connect below appears here as well.": "まだグループはありません。「新しいグループ」で動作中のエージェント会話から作れます。エージェント自身も作れます（vibespace-msg group create）。下で接続したアカウントの会話もすべてここに並びます。",
