  "No conversations yet — the first pass lists them.": "まだ会話はありません —— 最初の取得で一覧になります。",
  "Your live agent sessions on this instance — the same list as the sidebar. Assign one to another agent to have its messages followed.": "このインスタンスで動作中のエージェント会話 —— サイドバーと同じ一覧です。別のエージェントに割り当てると、そのメッセージが追われます。",
  "Your live agent sessions on this instance. Assigned ones wake the agent they are handed to.": "このインスタンスで動作中のエージェント会話。割り当て済みのものは任されたエージェントを起こします。",
  "Last wake was held or stashed — open the conversation's Assign & filter for the reason": "前回の起動は保留または格納されました —— 理由は会話の「割り当てとフィルタ」で確認できます",
