  "{name} is waiting for you: the plan awaits your approval": "{name} があなたを待っています：プランの承認待ち",
  "Stopped before it finished": "完了する前に停止されました",
  "The helper failed": "ヘルパーが失敗しました",
  "Nothing to answer is on screen — the request may have been settled already": "画面上に回答が必要なものはありません — すでに処理済みの可能性があります",
  // lane S1 verify r1: a stale answer is refused with a word
  "Already answered — allowed. Nothing was sent.": "すでに回答済み — 許可。今回は何も送信されていません。",
  "Already answered — denied. Nothing was sent.": "すでに回答済み — 拒否。今回は何も送信されていません。",
  "No longer waiting — the helper was stopped. Nothing was sent.": "もう待っていません — ヘルパーは停止されました。今回は何も送信されていません。",
  "No longer waiting — the helper has finished. Nothing was sent.": "もう待っていません — ヘルパーは終了しました。今回は何も送信されていません。",
