  "No longer waiting — this request belongs to a process that ended": "待機は終了しました — このリクエストは終了したプロセスのものです",
  "This answer did not reach the agent: the conversation ended. Nothing was sent.": "この回答はエージェントに届きませんでした：会話は終了しています。今回は何も送信されていません。",
  "This answer did not reach the agent: no running session holds this request. Nothing was sent.": "この回答はエージェントに届きませんでした：このリクエストを保持している実行中のセッションはありません。今回は何も送信されていません。",
  "Ended — reason unknown (the CLI wrote a result VibeSpace does not recognise)": "終了——理由不明（CLI が書いた結果を VibeSpace が認識できません）",
  "Not run — the request was withdrawn or the turn ended before an answer": "未実行——リクエストが取り下げられたか、回答前にターンが終了しました",
  "Already ended — reason unknown. Nothing was sent.": "すでに終了——理由不明。何も送信されませんでした。",
  // R4 (2026-09-27): access and notification — two operations, access first; compose (B-6acc)
  "That rule no longer exists": "そのルールはもう存在しません",
  "Grant access — {title}": "アクセスを許可 — {title}",
  "Notify — {title}": "通知 — {title}",
  "Grant access to the whole account — {label}": "アカウント全体へのアクセスを許可 — {label}",
  "Notify on the whole account — {label}": "アカウント全体の通知 — {label}",
  "Grant access to the conversations matching a rule — {label}": "ルールに一致する会話へのアクセスを許可 — {label}",
  "Notify on the conversations matching a rule — {label}": "ルールに一致する会話の通知 — {label}",
  "Who may see every conversation of this account — now and later — and act on them: read, search, refresh, reply (and write a new message where the account can). Access alone never wakes anyone.": "このアカウントの会話を（今後のものも含めて）すべて見て対応できる人：閲覧・検索・更新・返信（アカウントが対応していれば新規メッセージの作成も）。アクセス権だけでは誰も起動されません。",
  "Who may see the conversations that match the rule — now and later — and act on them. Access alone never wakes anyone.": "ルールに一致する会話（今後のものも含む）を見て対応できる人。アクセス権だけでは誰も起動されません。",
  "Who may see this conversation and act on it: read, search, refresh and reply. Access alone never wakes anyone.": "この会話を見て対応できる人：閲覧・検索・更新・返信。アクセス権だけでは誰も起動されません。",
  "Add an agent or group": "エージェントまたはグループを追加",
  "Nobody has access — saving removes everyone's access (and their notifications).": "誰にもアクセス権がありません — 保存すると全員のアクセス権（と通知）が削除されます。",
  "Removing access also removes the notification of: {list}": "アクセス権を削除すると、次の通知も削除されます：{list}",
  "The rule is removed — its access and notifications with it": "ルールを削除しました — そのアクセス権と通知も削除されました",
  "Notify…": "通知…",
  "A rule needs at least one agent or group with access": "ルールには、アクセス権を持つエージェントまたはグループが少なくとも 1 つ必要です",
  "Access saved: {list} — nobody is woken unless you add a notification (Notify…)": "アクセス権を保存しました：{list} — 通知（通知…）を追加しない限り誰も起動されません",
  "Access removed": "アクセス権を削除しました",
  "Remove this notification": "この通知を削除",
  "Authority comes from its access: {authority}": "権限はそのアクセス権によります：{authority}",
  "Grant access first — use \"Grant access…\". Only an agent or group with access here can be notified.": "先にアクセスを許可してください — 「アクセスを許可…」を使います。ここでアクセス権を持つエージェントまたはグループだけが通知を受けられます。",
  "Grant access…": "アクセスを許可…",
  "Who is woken when new messages arrive here, and on what. Only the agents and groups with access are listed; nobody listed = nobody is woken.": "ここに新しいメッセージが届いたとき、誰をどの条件で起動するか。アクセス権を持つエージェントとグループだけが表示されます。誰も選ばなければ誰も起動されません。",
  "Also notified here through the account or a rule: {list}. A notification saved here replaces that agent's own for this conversation only.": "アカウントまたはルール経由でもここで通知されます：{list}。ここで保存した通知は、この会話に限りそのエージェント自身の通知を置き換えます。",
  "Add a notification": "通知を追加",
  "In all: about {n} wakes a day — each notification has its own cap": "合計：1 日あたり約 {n} 回の起動 — 通知ごとに上限があります",
  "Nobody is notified — saving wakes nobody (access stays).": "誰にも通知しません — 保存しても誰も起動されません（アクセス権は残ります）。",
  "Save the rule's access first": "先にこのルールのアクセス権を保存してください",
  "Notifications saved: {list}": "通知を保存しました：{list}",
  "numbers past their bounds were kept at the bound": "範囲外の数値は上限・下限に合わせました",
  "Nobody is notified here any more": "ここでは誰にも通知しなくなりました",
