  "{who} has no access here — grant access first (Grant access…), then notify": "{who} にはここでのアクセス権がありません — 先にアクセスを許可（アクセスを許可…）してから通知を設定してください",
  "At most {n} rows per list": "リストごとに最大 {n} 行です",
  "This account cannot start a new conversation — reply inside an existing one": "このアカウントでは新しい会話を始められません — 既存の会話で返信してください",
  "wake per batch": "バッチごとに起動",
  "on a filter": "フィルター条件で",
