  "Access: {list}": "アクセス：{list}",
  "Notify: {list}": "通知：{list}",
  "Notify: nobody": "通知：なし",
  "kept at the minimum, {n}": "最小値 {n} にしました",
  "kept at the maximum, {n}": "最大値 {n} にしました",
  "The whole account: who may see and act on every conversation, and who is woken. Click for Grant access… / Notify….": "アカウント全体：すべての会話を見て対応できる人と、起動される人。クリックで「アクセスを許可…」/「通知…」。",
  "Rule: {rule} → {grant}": "ルール：{rule} → {grant}",
  "Conversations matching this rule — now and later. Click for Grant access… / Notify….": "このルールに一致する会話（今後のものも含む）。クリックで「アクセスを許可…」/「通知…」。",
  "Grant access… / Notify…": "アクセスを許可… / 通知…",
