  "1 group message rides the next turn, after this one ends": "グループメッセージ 1 件は、このターンが終わった後の次のターンと一緒に届きます",
  "{n} group messages ride the next turn, after this one ends": "グループメッセージ {n} 件は、このターンが終わった後の次のターンと一緒に届きます",
  "this agent is mid-turn — they ride the next turn, after this one ends": "このエージェントはターンの実行中です — このターンが終わった後の次のターンと一緒に届きます",
  "This agent is mid-turn — a message typed into a running turn carries no group message; they ride its next turn after this one ends, whoever starts it, or at once when a member @mentions it": "このエージェントはターンの実行中です — 実行中のターンに入力したメッセージはグループメッセージを運びません。このターンが終わった後の次のターン（誰が始めても）と一緒に届き、メンバーが @ で呼んだときはすぐに届きます",
  "This agent has no live inbox and is mid-turn — every waiting notice rides its next turn, after this one ends": "このエージェントには受信口がなく、ターンの実行中です — 待っている通知はすべて、このターンが終わった後の次のターンと一緒に届きます",
  "A hand-over is on its way": "引き渡しが進行中です",
  "This agent has no live inbox — every waiting notice rides its next turn": "このエージェントにはライブの受信箱がありません — 待っている通知はすべて次のターンと一緒に届きます",
  "Handed over {n} waiting notice(s); {h} more are still held — hand over again or send a message": "待っていた通知 {n} 件を渡しました。あと {h} 件はまだ保留中です — もう一度渡すかメッセージを送ってください",
  // §25 the render layer (channel-blocks-view.js / channel-window.js)
  "Sticker": "スタンプ",
  "Shared a chat": "グループチャットを共有しました",
  "Shared a contact": "連絡先を共有しました",
