  "The last 50 commands agents ran on {machine}, newest first; a row opens its output (the first 4 KiB of each stream).": "エージェントが {machine} で実行した直近 50 件のコマンド（新しい順）。行を開くとその出力（各ストリームの先頭 4 KiB）が見られます。",
