  "{n} {label} keys": "{label} のキー {n} 件",
  "The company presets file {file} could not be read ({code}) — the previous presets are kept.": "会社のプリセットファイル {file} を読み込めませんでした（{code}）— 以前のプリセットをそのまま使います。",
  "The company presets file {file} could not be read ({code}) — it offers no presets until it is fixed.": "会社のプリセットファイル {file} を読み込めませんでした（{code}）— 直るまでこのファイルのプリセットはありません。",
  "Company presets: none — ask your admin.": "会社のプリセット: なし — 管理者に依頼してください。",
  "{list} — from the environment (a restart is needed to change them)": "{list} — 環境変数から（変更には再起動が必要）",
  "{list} — from the cluster": "{list} — クラスターから",
  "{list} — from this release’s own values": "{list} — このリリース自身の値から",
  "{from}, updated {ago}": "{from}、{ago}に更新",
  "Company presets: {parts}": "会社のプリセット: {parts}",
  "Read from {dir} — it updates without a restart.": "{dir} から読み込み — 再起動なしで更新されます。",
  "No company OAuth client on this instance — ask your admin. Meanwhile the built-in client works, and your own avoids rclone's shared quota.": "このインスタンスには会社の OAuth クライアントがありません — 管理者に依頼してください。それまでは組み込みクライアントが使え、自分のクライアントなら rclone の共有クォータを避けられます。",
  "No company OAuth client on this instance — ask your admin, or provide your own (it needs the gmail.readonly scope).": "このインスタンスには会社の OAuth クライアントがありません — 管理者に依頼するか、自分のクライアントを指定してください（gmail.readonly スコープが必要です）。",
  "No company {name} client on this instance — ask your admin, or use your own client.": "このインスタンスには会社の {name} クライアントがありません — 管理者に依頼するか、自分のクライアントを使ってください。",
  "a notice being retried": "再送中の通知 1 件",
  "{n} notices being retried": "再送中の通知 {n} 件",
  "{name} · being retried": "{name} · 再送中",
  "1 notice is being retried for this agent": "この agent へ通知 1 件を再送しています",
  "{n} notices are being retried for this agent": "この agent へ通知 {n} 件を再送しています",
  "next attempt {when} or when this turn ends": "次の試行：{when}、またはこのターンの終了時",
