  "A comment in the changes is at most {n} characters": "変更リスト内のコメントは最大 {n} 文字です",
  "Added — 1 change waits. Pick the next element, or Send all.": "追加しました — 1 件の変更が待機中。次の要素を選ぶか、「すべて送信」を押してください。",
  "Added — {n} changes wait. Pick the next element, or Send all.": "追加しました — {n} 件の変更が待機中。次の要素を選ぶか、「すべて送信」を押してください。",
  "Present": "プレゼン",
  "Presentation": "プレゼン",
