  "Asked {vendor}'s whole mailbox: {n} not saved here — may be related": "{vendor}のメールボックス全体を検索しました：ここに未保存の {n} 件 — 関連する可能性があります",
  "This channel offers no search of its own": "このチャネルには独自の検索がありません",
