  "Tweaks": "微調整",
  "Every knob back to the agent's default": "すべてのノブを agent の既定値に戻す",
  "Changes show at once — nothing is sent to the agent.": "変更はすぐに反映されます — agent には何も送られません。",
  "This design has no tweaks yet.": "このデザインにはまだ微調整の項目がありません。",
  "Ask the agent for knobs — an accent colour, corner radius, density, type, dark / light — then try them here without another turn.": "agent にノブを頼みましょう — アクセントカラー、角の丸み、密度、書体、ダーク / ライト — その後はここで試せます。追加のターンは要りません。",
