  "\"{name}\" leaves this list and the chat's design chip. The folder and its files stay as they are: {dir}": "「{name}」をこの一覧とチャットのデザインボタンから外します。フォルダーとファイルはそのまま残ります：{dir}",
  "Remove from the list": "一覧から外す",
